(1458237, 190165, 39075, '<td valign="top">Good use of shadows.</td>', 'Good use of shadows.', '2005-06-15 15:05:06.000000', NULL, 1),
(1458238, 189525, 20530, '<td valign="top">Very nice. Brings up a lot of emotion for me. Glad I looked at it carefully. I almost missed the figure in the doorway. Nice contradiction with the cheerful colors and depressing grunge.</td>', 'Very nice. Brings up a lot of emotion for me. Glad I looked at it carefully. I almost missed the figure in the doorway. Nice contradiction with the cheerful colors and depressing grunge.', '2005-06-15 15:05:10.000000', NULL, 1),
