(1458884, 188749, 39265, '<td valign="top">Very moving. 10</td>', 'Very moving. 10', '2005-06-15 19:19:01.000000', NULL, 1),
(1458886, 188749, 36472, '<td valign="top">Wow....all I can say. Brings me to near tears. Losing a child.....utter darkness indeed.</td>', 'Wow....all I can say. Brings me to near tears. Losing a child.....utter darkness indeed.', '2005-06-15 19:19:25.000000', NULL, 1),
