(1461501, 187981, 36050, '<td valign="top">maybe show little bit more the eye expresion.</td>', 'maybe show little bit more the eye expresion.', '2005-06-16 19:30:39.000000', NULL, 1),
(1461509, 189296, 4226, '<td valign="top">Nice smoke capture</td>', 'Nice smoke capture', '2005-06-16 19:35:10.000000', NULL, 1),
(1461512, 190164, 4226, '<td valign="top">Looks too posed.. its difficult for the guy to be sleeping like this on stairs and still holding the bottle.. once you sleep it willl fall down unless its resting on something which is not.. your hands can''t hold it while sleeping :).. also the cigarette is lighted (?) .. <br/>Other than that, nice idea,moody but you got to make it look real :) 6</td>', 'Looks too posed.. its difficult for the guy to be sleeping like this on stairs and still holding the bottle.. once you sleep it willl fall down unless its resting on something which is not.. your hands can''t hold it while sleeping :).. also the cigarette is lighted (?) .. Other than that, nice idea,moody but you got to make it look real :) 6', '2005-06-16 19:36:58.000000', NULL, 1),
(1461513, 189034, 36981, '<td valign="top">I love this interpretation &amp; composition.  I do wish it were a bit more in focus, though.</td>', 'I love this interpretation & composition.  I do wish it were a bit more in focus, though.', '2005-06-16 19:37:31.000000', NULL, 1),
(1461514, 190212, 38492, '<td valign="top">Nice shot of the singer, and great capture of the light beams. against the darkness. The emotion on his face is superb! 7</td>', 'Nice shot of the singer, and great capture of the light beams. against the darkness. The emotion on his face is superb! 7', '2005-06-16 19:37:31.000000', NULL, 1),
(1461516, 190185, 4226, '<td valign="top">Fireworks are for joy, celebration and light and I don''t know how it represents darkness ?? sorry but 3</td>', 'Fireworks are for joy, celebration and light and I don''t know how it represents darkness ?? sorry but 3', '2005-06-16 19:37:55.000000', NULL, 1),
