(1462892, 189461, 39021, '<td valign="top">I''d crop out almost half the grass side leaving an almost square picture.</td>', 'I''d crop out almost half the grass side leaving an almost square picture.', '2005-06-17 08:16:11.000000', NULL, 1),
(1462893, 187923, 35602, '<td valign="top">Don''t see serenity in this shot.  The facial expression doesn''t seem very peaceful.</td>', 'Don''t see serenity in this shot.  The facial expression doesn''t seem very peaceful.', '2005-06-17 08:18:23.000000', NULL, 1),
