(1465418, 189732, 32754, '<td valign="top">I don''t really understand it, but it has undeniable graphic power.</td>', 'I don''t really understand it, but it has undeniable graphic power.', '2005-06-18 14:52:31.000000', NULL, 1),
(1465424, 189410, 32754, '<td valign="top">Very effective and thought provoking shot.</td>', 'Very effective and thought provoking shot.', '2005-06-18 14:54:18.000000', NULL, 1),
(1465426, 187475, 32754, '<td valign="top">Very cool!  I like the use of reds in this and repetition of images.</td>', 'Very cool!  I like the use of reds in this and repetition of images.', '2005-06-18 14:54:50.000000', NULL, 1),
(1465427, 188556, 32754, '<td valign="top">Lovely tones to this macro; excellent focus anad placement of subject.</td>', 'Lovely tones to this macro; excellent focus anad placement of subject.', '2005-06-18 14:55:30.000000', NULL, 1),
(1465428, 187746, 32754, '<td valign="top">I like it but maybe a little too dark, it''s difficult to pick out the image..but the darkness is effective with the cowl over head.</td>', 'I like it but maybe a little too dark, it''s difficult to pick out the image..but the darkness is effective with the cowl over head.', '2005-06-18 14:56:51.000000', NULL, 1),
(1465430, 190254, 32754, '<td valign="top">This is really eerie..I like it: the tone, the stretchers all add to the mystery.</td>', 'This is really eerie..I like it: the tone, the stretchers all add to the mystery.', '2005-06-18 14:58:57.000000', NULL, 1),
(1465437, 188596, 38078, '<td valign="top">The blank page is one of the most thought-provoking images for a writer/artist such as myself.</td>', 'The blank page is one of the most thought-provoking images for a writer/artist such as myself.', '2005-06-18 15:02:10.000000', NULL, 1),
(1465439, 190233, 38078, '<td valign="top">the darkness of the forest is not overwhelming or foreboding.  But the path that leads in adds an element of mystery.</td>', 'the darkness of the forest is not overwhelming or foreboding.  But the path that leads in adds an element of mystery.', '2005-06-18 15:03:06.000000', NULL, 1),
