(1465531, 189163, 29651, '<td valign="top">very neat photo. is it water or fire or both?</td>', 'very neat photo. is it water or fire or both?', '2005-06-18 16:13:15.000000', NULL, 1),
(1465532, 189347, 38078, '<td valign="top">a little goofy looking.  fun shot.</td>', 'a little goofy looking.  fun shot.', '2005-06-18 16:13:39.000000', NULL, 1),
(1465533, 189592, 29651, '<td valign="top">this is dark and what is this?</td>', 'this is dark and what is this?', '2005-06-18 16:13:48.000000', NULL, 1),
