INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1472512, 190288, 37632, '<td valign="top">I assume that this is supposed to be an angel of some sort.  The photo does not sufficiently define this.</td>', 'I assume that this is supposed to be an angel of some sort.  The photo does not sufficiently define this.', '2005-06-22 00:45:56.000000', NULL, 1),
(1472516, 190194, 6008, '<td valign="top">Hrm, this looks familiar. Wichita! I think it may have been better had you got more of the doors in the shot to suggest what is behind them and also show more of the fear of death. Too much bright sunlight for a lot of people I imagine.</td>', 'Hrm, this looks familiar. Wichita! I think it may have been better had you got more of the doors in the shot to suggest what is behind them and also show more of the fear of death. Too much bright sunlight for a lot of people I imagine.', '2005-06-22 00:46:43.000000', NULL, 1),
